import{_ as e,o as n,c as a,a5 as r}from"./chunks/framework.CsGesDJn.js";const s=JSON.parse('{"title":"03 — Agency & Workspace Management (chi tiết FR)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/03-agency-workspace-management.md","filePath":"ba/03-agency-workspace-management.md"}'),d={name:"ba/03-agency-workspace-management.md"};function i(c,t,h,o,g,m){return n(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="_03-—-agency-workspace-management-chi-tiet-fr" tabindex="-1">03 — Agency &amp; Workspace Management (chi tiết FR) <a class="header-anchor" href="#_03-—-agency-workspace-management-chi-tiet-fr" aria-label="Permalink to &quot;03 — Agency &amp; Workspace Management (chi tiết FR)&quot;">​</a></h1><p>&gt; <a href="./00-overview.html">&lt;&lt; Về Overview</a> — Xem mô hình tổng quan tại <a href="./01-organization-structure.html">01-organization-structure.md</a> trước khi đọc file này.</p><p>File này liệt kê đầy đủ 21 FR nhóm 3.4 kèm chi tiết nghiệp vụ. Phần diễn giải mô hình/quan hệ đã có ở file 01 — file này tập trung vào từng FR cụ thể.</p><h2 id="danh-sach-fr-đay-đu" tabindex="-1">Danh sách FR đầy đủ <a class="header-anchor" href="#danh-sach-fr-đay-đu" aria-label="Permalink to &quot;Danh sách FR đầy đủ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>FR</th><th>Tên</th><th>Role</th><th>Mô tả</th></tr></thead><tbody><tr><td>3.4.1</td><td>List Agency</td><td>OWNER</td><td>Trang list các Agency mà user đang sở hữu (là owner)</td></tr><tr><td>3.4.2</td><td>View Agency Dashboard</td><td>OWNER</td><td>Coi thông tin tổng quan của công ty</td></tr><tr><td>3.4.3</td><td>Create Agency</td><td>OWNER</td><td>Có owner id liên kết 1-1 với id user tạo ra agency</td></tr><tr><td>3.4.4</td><td>View Agency Profile</td><td>OWNER</td><td>Coi thông tin công ty — đại diện để khách hàng hiểu về Agency</td></tr><tr><td>3.4.5</td><td>Update Agency Profile</td><td>OWNER</td><td>Update thông tin Agency</td></tr><tr><td>3.4.6</td><td>Remove Agency</td><td>OWNER</td><td>Xóa mềm, có confirm, khôi phục được trong 30 ngày</td></tr><tr><td>3.4.7</td><td>Invite Agency Member</td><td>OWNER</td><td>Mời qua mail + notification; người được mời không có role gì, chỉ là member thông thường</td></tr><tr><td>3.4.8</td><td>View Agency Invitation Status</td><td>OWNER / USER (invited)</td><td>Cả 2 bên thấy được lời mời; tự hết hạn sau 3 ngày</td></tr><tr><td>3.4.9</td><td>Remove Member</td><td>OWNER</td><td>Xóa member khỏi Agency — mất quyền truy cập nhưng tài nguyên họ tạo ra vẫn giữ (tài sản chung); thêm lại vẫn dùng tiếp được</td></tr><tr><td>3.4.10</td><td>List Workspace</td><td>OWNER / MEMBER</td><td>Member chỉ coi workspace mình có mặt; Owner coi toàn bộ</td></tr><tr><td>3.4.11</td><td>View Workspace Dashboard</td><td>OWNER / MEMBER</td><td>Thông tin chung + thống kê workspace</td></tr><tr><td>3.4.12</td><td>Create Workspace</td><td>OWNER</td><td>Bắt buộc thêm ít nhất 1 thành viên và gán làm Manager của workspace đó, toàn quyền quản lý. <strong>[CONFIRMED 2026-09-15]</strong> Owner được tự gán mình làm Manager. Mỗi Workspace chỉ đúng 1 Manager — không co-manage; đổi Manager = re-assign (Manager cũ mất quyền).</td></tr><tr><td>3.4.13</td><td>View Workspace Profile</td><td>OWNER / MANAGER</td><td>Update được Timezone Configuration — mốc thời gian chuẩn hoạt động của workspace, hỗ trợ tối ưu giờ đăng bài theo địa điểm</td></tr><tr><td>3.4.14</td><td>Update Workspace Profile</td><td>OWNER / MANAGER</td><td>Update thông tin workspace</td></tr><tr><td>3.4.15</td><td>Delete Workspace</td><td>OWNER</td><td>Chỉ Owner xóa được, khôi phục trong 30 ngày; khi xóa toàn bộ member mất quyền truy cập, data chuyển inactive</td></tr><tr><td>3.4.16</td><td>Leave Workspace</td><td>MEMBER</td><td>Rời workspace nhưng vẫn còn trong Agency</td></tr><tr><td>3.4.17</td><td>Save Workspace Template</td><td>OWNER</td><td>Lưu lại workspace hiện có thành template để tái sử dụng khi tạo workspace mới</td></tr><tr><td>3.4.18</td><td>View Workspace Members</td><td>MEMBER</td><td>Coi danh sách thành viên</td></tr><tr><td>3.4.19</td><td>Add Workspace Member</td><td>OWNER / MANAGER</td><td>Thêm member (đã có trong Agency) vào workspace với role cụ thể</td></tr><tr><td>3.4.20</td><td>Update Workspace Member Role</td><td>OWNER / MANAGER</td><td>Đổi role của member trong workspace đó</td></tr><tr><td>3.4.21</td><td>Remove Workspace Member</td><td>OWNER / MANAGER</td><td>Xóa thành viên khỏi workspace (không xóa khỏi Agency)</td></tr></tbody></table><h2 id="luu-y-nghiep-vu-quan-trong" tabindex="-1">Lưu ý nghiệp vụ quan trọng <a class="header-anchor" href="#luu-y-nghiep-vu-quan-trong" aria-label="Permalink to &quot;Lưu ý nghiệp vụ quan trọng&quot;">​</a></h2><h3 id="invitation-co-thoi-han-3-4-8" tabindex="-1">Invitation có thời hạn (3.4.8) <a class="header-anchor" href="#invitation-co-thoi-han-3-4-8" aria-label="Permalink to &quot;Invitation có thời hạn (3.4.8)&quot;">​</a></h3><ul><li>Lời mời vào Agency <strong>tự động hết hạn sau 3 ngày</strong> nếu không được accept/reject.</li><li>Cả người mời (Owner) và người được mời (User) đều thấy trạng thái lời mời đang chờ.</li></ul><h3 id="xoa-mem-soft-delete-—-ap-dung-nhat-quan" tabindex="-1">Xóa mềm (soft delete) — áp dụng nhất quán <a class="header-anchor" href="#xoa-mem-soft-delete-—-ap-dung-nhat-quan" aria-label="Permalink to &quot;Xóa mềm (soft delete) — áp dụng nhất quán&quot;">​</a></h3><ul><li>Remove Agency (3.4.6): 30 ngày khôi phục.</li><li>Delete Workspace (3.4.15): 30 ngày khôi phục.</li><li>Cả 2 đều yêu cầu bước confirm trước khi thực hiện xóa.</li></ul><h3 id="member-vs-role-—-2-khai-niem-tach-biet-hoan-toan-nhac-lai-tu-file-01" tabindex="-1">Member vs Role — 2 khái niệm tách biệt hoàn toàn (nhắc lại từ file 01) <a class="header-anchor" href="#member-vs-role-—-2-khai-niem-tach-biet-hoan-toan-nhac-lai-tu-file-01" aria-label="Permalink to &quot;Member vs Role — 2 khái niệm tách biệt hoàn toàn (nhắc lại từ file 01)&quot;">​</a></h3><ul><li>&quot;Thêm vào Agency&quot; (3.4.7) ≠ &quot;Có Role&quot;. Vào Agency chỉ là thành viên công ty.</li><li>&quot;Role&quot; chỉ xuất hiện khi thao tác Add Workspace Member (3.4.19) — role đó CHỈ áp dụng cho đúng Workspace đang thêm vào, không lan sang Workspace khác trong cùng Agency.</li></ul><h3 id="quan-he-agency-member-↔-workspace-member" tabindex="-1">Quan hệ Agency Member ↔ Workspace Member <a class="header-anchor" href="#quan-he-agency-member-↔-workspace-member" aria-label="Permalink to &quot;Quan hệ Agency Member ↔ Workspace Member&quot;">​</a></h3><ul><li>Điều kiện để add ai đó vào Workspace: <strong>họ phải đã là Member của Agency đó trước</strong> (FR 3.4.19: &quot;Thêm member trong Agency vào workspace với role cụ thể&quot;).</li><li>Tức là: chưa vào Agency → không thể trực tiếp vào Workspace của Agency đó.</li></ul>',14)])])}const u=e(d,[["render",i]]);export{s as __pageData,u as default};
